INSERT INTO `csc364chms`.`events` (`Event_ID`,`Event_Title`,`Event_Description`,`Event_Start_Date`,`Event_End_Date`) VALUES (2910, 'Crawfish Jam', 'A family-friendly event from 6-9 pm May 10th with your choice of either a crawfish meal that includes 2 pounds of fresh crawfish, potatoes and corn or a hot dog meal. No tickets are needed for the entertainment, but IS required for the crawfish meal. Crawfish meal is $10 and available to the first 300 that register or $12.00 at the door. Registration will close May 6th. There will be live music with The Dolan Band, bounce houses for the kiddos, and a corn hole tournament. So grab your family and friends, be sure to bring your lawn chairs and or a blanket.  Please email Megan Robinson megan@mega.church if you have questions concerning your registration.   More info: http://events.mega.church/?id=2910 ', '2019-10-05 00:00:00', '2019-10-05 00:00:00'),(2919, 'Crew ', 'Legacy Event from Events Calendar', '2019-06-02 00:00:00', '2019-06-02 00:00:00'),(3683, 'Pathfinders Class', 'If you have decided to learn more about what it means for Megachurch to be your church home, your next step is to attend our Pathfinder\'s class.  Registration link: https://my.mega.church/portal/event_detail.aspx?id=8023', '2019-11-08 00:00:00', '2019-11-08 00:00:00'),(3684, 'Megachurch Golf Tournament', 'This is a relaxed, fun-filled day on Southern Oaks Golf Course in Burleson,TX. This is truly an open event with men, ladies and junior golfers invited to participate. Registration fee includes breakfast and lunch. Cost is $100.00 per person or $400.00 per foursome. You do have the option to pay with credit card, e-check or pay at the door. Registration closes 6-11 or at 144 people; check in at 7 am, shotgun at 8 am. Contact Kirk Trimble for questions concerning the tournament: kirktmsg@aol.com  Registration link: https://my.mega.church/portal/event_detail.aspx?id=3684&filter=month:6|year:2019|campus:0|ministry:0|listview:0|featuredevents:0', '2019-01-06 00:00:00', '2019-01-06 00:00:00'),(4320, 'Saturday 6pm Check-In', 'This event allows children to check-in during weekend services', '2019-02-02 00:00:00', '2019-02-02 00:00:00'),(4323, 'Sunday 9am EC, Children & Student Check-in', 'Check-in for all ages infants-students for Sunday 9am WS', '2019-10-02 00:00:00', '2019-10-02 00:00:00'),(4324, 'Sunday 10:25am EC, Children & Student Check-in', 'Check-in for all ages infants-students for Sunday 10:25 WS', '2019-10-02 00:00:00', '2019-10-02 00:00:00'),(4737, 'Saturday Evening Children\'s Check-In', 'This event allows children to check-in during weekend services', '2019-09-02 00:00:00', '2019-09-02 00:00:00'),(4840, ' Sunday 11:50am EC, Children & Student Check-in', 'regular Sunday 11:50 EC, Children, and Students check-in WS', '2019-10-02 00:00:00', '2019-10-02 00:00:00'),(5028, 'Spring Break Mexico Mission Trip', 'Join us as we travel down to see our friends in Rio Bravo, Mexico as they continue to build casitas and relationships with the amazing people in this community.  ', '2019-09-03 00:00:00', '2019-01-03 00:00:00'),(5038, 'Crew ', 'Legacy Event from Events Calendar', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(5044, 'Sunday 9am Check-in', 'Check-in for all ages infants-students for Sunday 9am WS', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(5045, 'Sunday 11:50am Check-in', 'regular Sunday 11:50 EC, Children, and Students check-in WS', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(5046, 'Saturday 6pm Check-In', 'This event allows children to check-in during weekend services, ages infant-5 yrs old', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(5047, 'Sunday 10:25am Check-in', 'Check-in for all ages infants-students for Sunday 10:25 WS', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(6053, 'KidCare Check-In', 'This check-in is for KidCare mornings and evenings, NOT regular WS or Wednesday.', '2019-01-02 00:00:00', '2019-01-02 00:00:00'),(6056, 'Crew ', 'Legacy Event from Events Calendar', '2019-01-02 00: